"""Validation and derivation for generated RMSNorm calibration artifacts."""

import hashlib
import json
import math
import os
import re
import statistics
from pathlib import Path
from typing import Any

from kestrel_kernels.source_identity import semantic_python_source_bytes


SCHEMA_VERSION = 2
DERIVATION_VERSION = 1
CONFIG_KEYS = ("num_threads", "threads_per_row")
DEFAULT_CANDIDATES = ((32, 32), (64, 32), (128, 32), (256, 32), (64, 64))
PRODUCTION_WORKLOADS = ((1, 1.0), (13, 1.0), (128, 1.0))
TUNING_WEIGHT_DTYPES = ("bfloat16", "float32")
TUNING_SOURCE_FILES = {
    "runner_sha256": "scripts/tune_rmsnorm.py",
    "derivation_sha256": "python/kestrel_kernels/rmsnorm/calibration.py",
    "compiler_sha256": "scripts/precompile/families/rmsnorm.py",
    "kernel_sha256": "python/kestrel_kernels/rmsnorm/kernel.py",
    "copy_geometry_sha256": "python/kestrel_kernels/cute_copy.py",
}


def tuning_source_identities(source_root: Path | None = None) -> dict[str, str]:
    """Return semantic identities for the available RMSNorm tuning closure."""
    module_path = Path(__file__).resolve()
    if source_root is None:
        source_root = module_path.parents[3]
        paths = {"derivation_sha256": module_path}
        paths.update(
            {
                name: source_root / relative_path
                for name, relative_path in TUNING_SOURCE_FILES.items()
                if name != "derivation_sha256"
                and (source_root / relative_path).is_file()
            }
        )
    else:
        paths = {
            name: source_root / relative_path
            for name, relative_path in TUNING_SOURCE_FILES.items()
        }
        missing = [str(path) for path in paths.values() if not path.is_file()]
        if missing:
            raise RuntimeError(
                f"RMSNorm tuning source closure is incomplete: {missing}"
            )
    return {
        name: hashlib.sha256(semantic_python_source_bytes(path)).hexdigest()
        for name, path in paths.items()
    }


def _exact_json_value(value: object, expected: object) -> bool:
    if type(value) is not type(expected):
        return False
    if isinstance(expected, list):
        return len(value) == len(expected) and all(
            _exact_json_value(item, expected_item)
            for item, expected_item in zip(value, expected, strict=True)
        )
    return value == expected


def candidate_geometries(hidden_size: int) -> tuple[tuple[int, int], ...]:
    """Return the exhaustive valid geometry set for one vectorized width."""
    if (
        isinstance(hidden_size, bool)
        or not isinstance(hidden_size, int)
        or hidden_size <= 0
        or hidden_size % 4
    ):
        raise ValueError("RMSNorm hidden size must be a positive multiple of 4")

    vectors = hidden_size // 4
    standard = tuple(
        candidate for candidate in DEFAULT_CANDIDATES if vectors % candidate[1] == 0
    )
    if standard:
        return standard

    threads_per_row_options = tuple(
        threads_per_row
        for threads_per_row in (1, 2, 4, 8, 16, 32)
        if vectors % threads_per_row == 0
    )
    return tuple(
        (num_threads, threads_per_row)
        for threads_per_row in threads_per_row_options
        for num_threads in (32, 64, 128, 256)
        if threads_per_row <= num_threads
    )


def canonical_config(config: dict[str, Any]) -> dict[str, int]:
    if set(config) != set(CONFIG_KEYS):
        missing = sorted(set(CONFIG_KEYS) - set(config))
        extra = sorted(set(config) - set(CONFIG_KEYS))
        raise ValueError(
            f"invalid RMSNorm config keys: missing={missing}, extra={extra}"
        )
    if any(
        isinstance(config[key], bool) or not isinstance(config[key], int)
        for key in CONFIG_KEYS
    ):
        raise ValueError("RMSNorm config values must be integers")
    normalized = {key: config[key] for key in CONFIG_KEYS}
    num_threads = normalized["num_threads"]
    threads_per_row = normalized["threads_per_row"]
    if (
        num_threads <= 0
        or threads_per_row <= 0
        or num_threads % 32
        or num_threads % threads_per_row
        or (threads_per_row > 32 and threads_per_row != num_threads)
    ):
        raise ValueError("invalid RMSNorm thread geometry")
    return normalized


def config_identity(config: dict[str, Any]) -> str:
    encoded = json.dumps(
        canonical_config(config), sort_keys=True, separators=(",", ":")
    ).encode()
    return hashlib.sha256(encoded).hexdigest()[:16]


def summarize_samples(samples: list[float]) -> dict[str, float | int]:
    if len(samples) < 5:
        raise ValueError("each RMSNorm candidate needs at least 5 samples")
    normalized = [float(value) for value in samples]
    if any(not math.isfinite(value) or value <= 0 for value in normalized):
        raise ValueError("RMSNorm timing samples must be finite and positive")
    median_us = statistics.median(normalized)
    deviations = [abs(value - median_us) for value in normalized]
    return {
        "count": len(normalized),
        "median_us": round(median_us, 6),
        "mad_us": round(statistics.median(deviations), 6),
        "min_us": round(min(normalized), 6),
        "max_us": round(max(normalized), 6),
    }


def make_candidate(
    config: dict[str, Any],
    *,
    samples_us: list[float],
    correctness: dict[str, Any],
) -> dict[str, Any]:
    normalized = canonical_config(config)
    rounded = [round(float(value), 6) for value in samples_us]
    return {
        "identity": config_identity(normalized),
        "config": normalized,
        "samples_us": rounded,
        "summary": summarize_samples(rounded),
        "correctness": correctness,
    }


def _validate_workload(
    workload_key: str, workload: dict[str, Any]
) -> list[dict[str, Any]]:
    rows = workload.get("rows")
    weight_dtype = workload.get("weight_dtype")
    if (
        isinstance(rows, bool)
        or not isinstance(rows, int)
        or weight_dtype not in ("bfloat16", "float32")
        or workload_key != f"{weight_dtype}:{rows}"
    ):
        raise ValueError(f"invalid RMSNorm workload identity {workload_key!r}")
    if rows <= 0:
        raise ValueError("RMSNorm workload rows must be positive")
    weight = workload.get("weight")
    if (
        isinstance(weight, bool)
        or not isinstance(weight, (int, float))
        or not math.isfinite(float(weight))
        or float(weight) <= 0
    ):
        raise ValueError("RMSNorm workload weight must be finite and positive")
    candidates = workload.get("candidates")
    if not isinstance(candidates, list) or not candidates:
        raise ValueError("RMSNorm workload has no candidates")
    seen: set[str] = set()
    for candidate in candidates:
        config = canonical_config(candidate.get("config", {}))
        identity = config_identity(config)
        if candidate.get("identity") != identity or identity in seen:
            raise ValueError("invalid or duplicate RMSNorm candidate identity")
        seen.add(identity)
        summary = summarize_samples(candidate.get("samples_us", []))
        if candidate.get("summary") != summary:
            raise ValueError("RMSNorm summary is not derived from raw samples")
        correctness = candidate.get("correctness")
        if not isinstance(correctness, dict) or correctness.get("passed") is not True:
            raise ValueError("RMSNorm candidate lacks passing correctness evidence")
        for metric in ("max_abs", "relative_l2"):
            value = correctness.get(metric)
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(float(value))
                or float(value) < 0
            ):
                raise ValueError(f"invalid RMSNorm correctness metric {metric}")
    return candidates


def derive_selection(workloads: dict[str, Any]) -> dict[str, Any]:
    if not workloads:
        raise ValueError("RMSNorm calibration has no workloads")
    scores: dict[str, float] = {}
    configs: dict[str, dict[str, int]] = {}
    total_weight = 0.0
    expected_identities: set[str] | None = None
    for workload_key in sorted(workloads):
        workload = workloads[workload_key]
        candidates = _validate_workload(workload_key, workload)
        identities = {candidate["identity"] for candidate in candidates}
        if expected_identities is None:
            expected_identities = identities
        elif identities != expected_identities:
            raise ValueError("RMSNorm workloads measured different candidate sets")
        fastest = min(
            float(candidate["summary"]["median_us"]) for candidate in candidates
        )
        weight = float(workload["weight"])
        total_weight += weight
        for candidate in candidates:
            identity = candidate["identity"]
            configs[identity] = canonical_config(candidate["config"])
            ratio = float(candidate["summary"]["median_us"]) / fastest
            scores[identity] = scores.get(identity, 0.0) + weight * math.log(ratio)
    winner = min(scores, key=lambda identity: (scores[identity], identity))
    return {
        "identity": winner,
        "config": configs[winner],
        "weighted_geomean_slowdown": round(math.exp(scores[winner] / total_weight), 9),
    }


def validate_artifact(
    data: dict[str, Any],
    *,
    expected_gpu_name: str,
    expected_compute_capability: str,
) -> dict[str, int]:
    if data.get("schema_version") != SCHEMA_VERSION:
        raise ValueError("unsupported RMSNorm calibration schema")
    hidden_size = data.get("hidden_size")
    if (
        isinstance(hidden_size, bool)
        or not isinstance(hidden_size, int)
        or hidden_size <= 0
    ):
        raise ValueError("invalid RMSNorm hidden size")
    calibration = data.get("calibration")
    if not isinstance(calibration, dict):
        raise ValueError("generated RMSNorm config is missing calibration evidence")
    if (
        type(calibration.get("derivation_version")) is not int
        or calibration["derivation_version"] != DERIVATION_VERSION
    ):
        raise ValueError("stale RMSNorm calibration derivation")
    provenance = calibration.get("provenance")
    required = {
        "generator",
        "source",
        "generated_at_utc",
        "gpu_name",
        "compute_capability",
        "torch_version",
        "cutlass_version",
    }
    if not isinstance(provenance, dict) or not required <= set(provenance):
        raise ValueError("RMSNorm calibration provenance is incomplete")
    if provenance.get("gpu_name") != expected_gpu_name:
        raise ValueError(
            "RMSNorm calibration GPU does not match the requested target"
        )
    if provenance.get("compute_capability") != expected_compute_capability:
        raise ValueError(
            "RMSNorm calibration compute capability does not match the requested target"
        )
    source = provenance.get("source")
    if not isinstance(source, dict) or set(source) != set(TUNING_SOURCE_FILES):
        raise ValueError("RMSNorm tuning source identities are incomplete")
    if any(
        not isinstance(identity, str) or re.fullmatch(r"[0-9a-f]{64}", identity) is None
        for identity in source.values()
    ):
        raise ValueError("RMSNorm tuning source identity is malformed")
    if any(
        source[name] != identity
        for name, identity in tuning_source_identities().items()
    ):
        raise ValueError("RMSNorm calibration is stale for its available sources")

    expected_geometries = candidate_geometries(hidden_size)
    search = calibration.get("search")
    expected_search_candidates = [list(candidate) for candidate in expected_geometries]
    expected_search_workloads = [
        {"rows": rows, "weight": weight} for rows, weight in PRODUCTION_WORKLOADS
    ]
    if (
        not isinstance(search, dict)
        or not _exact_json_value(search.get("candidates"), expected_search_candidates)
        or not _exact_json_value(search.get("workloads"), expected_search_workloads)
        or not _exact_json_value(
            search.get("weight_dtypes"), list(TUNING_WEIGHT_DTYPES)
        )
    ):
        raise ValueError("RMSNorm calibration search is not exhaustive")
    expected_configs = [
        {"num_threads": num_threads, "threads_per_row": threads_per_row}
        for num_threads, threads_per_row in expected_geometries
    ]
    workloads = calibration.get("workloads", {})
    if not isinstance(workloads, dict):
        raise ValueError("RMSNorm calibration has invalid workloads")
    expected_workload_weights = {
        f"{weight_dtype}:{rows}": weight
        for weight_dtype in TUNING_WEIGHT_DTYPES
        for rows, weight in PRODUCTION_WORKLOADS
    }
    if set(workloads) != set(expected_workload_weights):
        raise ValueError("RMSNorm calibration workload profile is incomplete")
    for workload_key, workload in workloads.items():
        if not isinstance(workload, dict) or not _exact_json_value(
            workload.get("weight"), expected_workload_weights[workload_key]
        ):
            raise ValueError("RMSNorm calibration workload weight is not authoritative")
        candidates = workload.get("candidates") if isinstance(workload, dict) else None
        if (
            not isinstance(candidates, list)
            or any(not isinstance(candidate, dict) for candidate in candidates)
            or [
                canonical_config(candidate.get("config", {}))
                for candidate in candidates
            ]
            != expected_configs
        ):
            raise ValueError(
                "RMSNorm workload does not cover the exhaustive candidate set"
            )

    selection = derive_selection(workloads)
    if calibration.get("selection") != selection:
        raise ValueError("RMSNorm selection is not derived from raw measurements")
    config = canonical_config(data.get("config", {}))
    if config != selection["config"]:
        raise ValueError("RMSNorm runtime config is not derived from calibration")
    if hidden_size % 4 or hidden_size // 4 % config["threads_per_row"]:
        raise ValueError(
            "RMSNorm generated geometry does not vectorize the hidden size"
        )
    return config


def atomic_write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        with temporary.open("w") as handle:
            json.dump(payload, handle, indent=2)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


__all__ = [
    "DEFAULT_CANDIDATES",
    "DERIVATION_VERSION",
    "PRODUCTION_WORKLOADS",
    "SCHEMA_VERSION",
    "TUNING_SOURCE_FILES",
    "TUNING_WEIGHT_DTYPES",
    "atomic_write_json",
    "candidate_geometries",
    "canonical_config",
    "config_identity",
    "derive_selection",
    "make_candidate",
    "summarize_samples",
    "tuning_source_identities",
    "validate_artifact",
]
